/**
 * Boulders Classic 2026 (PGTI) — hardcoded tournament data.
 *
 * Generated by scripts/generate-boulder-data.mjs from the official extracted
 * tournament JSON (players, draws, hole-by-hole scores, final leaderboard,
 * cut and purse model). The frontend reads this module directly — no backend
 * or database involved.
 *
 * Per-hole yardages are championship-tee approximations; every score, name,
 * draw and prize figure is the official tournament data.
 */

export interface TournamentInfo {
  id: number;
  name: string;
  edition: string;
  course: string;
  location: string;
  country: string;
  startDate: string;
  endDate: string;
  par: number;
  yardage: number;
  prizeFund: number;
  currency: string;
  status: string;
  currentRound: number;
  champion: string;
  championToPar: number;
  format: string;
  cutRule: string;
  fieldSize: number;
  madeCut: number;
  description: string;
}

export interface CourseHole {
  hole: number;
  par: number;
  yards: number;
  difficulty: number;
}

export interface FieldPlayer {
  id: number;
  firstName: string;
  lastName: string;
  country: string;
  countryCode: string;
  code: string;
  city: string | null;
  age: number | null;
  entryType: string;
  status: "Made Cut" | "Missed Cut" | "Retired";
}

export interface LeaderboardEntry {
  id: number;
  position: string;
  r1: number | null;
  r2: number | null;
  r3: number | null;
  r4: number | null;
  thru: number;
  today: number | null;
  total: number;
  strokes: number;
  status: string;
  player: { firstName: string; lastName: string; country: string; countryCode: string };
  scorecards: { r1: number[]; r2: number[]; r3: number[]; r4: number[] };
}

export interface DrawGroup {
  id: number;
  round: number;
  teeTime: string;
  tee: string;
  playerNames: string[];
}

export interface PrizeRow {
  id: number;
  position: string;
  tied: boolean;
  sharedBy: number;
  amount: number;
}

export interface PastResult {
  id: number;
  year: number;
  champion: string;
  country: string;
  score: string;
  margin: string;
  runnerUp: string;
}

export type GalleryCategory =
  | "Tournament film"
  | "Round 1"
  | "Round 2"
  | "Round 4"
  | "Winner's moments"
  | "Press conference"
  | "The Champion";

export interface GalleryItem {
  id: number;
  type: "photo" | "video";
  title: string;
  category: GalleryCategory;
  round: number | null;
  src: string;
  poster?: string;
  duration?: string;
  featured?: boolean;
  span: "wide" | "tall" | "feature";
  description: string;
}

export interface TourPartner {
  name: string;
  src: string;
  tier: "Tour Partner" | "Partner";
}


